import React, { useState } from "react";
import styled from "styled-components";
import FastaTable from "../components/Fasta";
import VirulenceTable from "../components/Virulence";
import AmrTable from "../components/Amr";

const Container = styled.div`
  width: 100%;
  padding: 20px;
  display: flex;
  justify-content: center;
  align-items: center;
`;

const Wrapper = styled.div`
  width: 80%;
  max-width: 1200px;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const Title = styled.h1`
  font-size: 36px;
  font-weight: bold;
  color: #333;
  margin-bottom: 20px;
  text-align: center;
`;

const ButtonGroup = styled.div`
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
`;

const Button = styled.button`
  padding: 10px 20px;
  background-color: transparent;
  color: ${(props) => (props.selected ? "#007bff" : "#000")};
  border: 2px solid ${(props) => (props.selected ? "#007bff" : "#ccc")};
  border-radius: 5px;
  font-size: 25px;
  font-weight: ${(props) => (props.selected ? "bold" : "normal")};
  cursor: pointer;
  margin: 0 30px;
  &:last-child {
    margin-right: 0;
  }
`;

const Result = ({ fastaInfo, virulenceInfo, amrInfo }) => {
  const [selectedTab, setSelectedTab] = useState("Fasta");

  const handleTabClick = (tab) => {
    setSelectedTab(tab);
  };

  return (
    <Container>
      <Wrapper>
        <Title>Kết quả phân tích mẫu</Title>
        <ButtonGroup>
          <Button
            selected={selectedTab === "Fasta"}
            onClick={() => handleTabClick("Fasta")}
          >
            Fasta
          </Button>
          <Button
            selected={selectedTab === "Virulence"}
            onClick={() => handleTabClick("Virulence")}
          >
            Virulence
          </Button>
          <Button
            selected={selectedTab === "AMR"}
            onClick={() => handleTabClick("AMR")}
          >
            AMR
          </Button>
        </ButtonGroup>

        {selectedTab === "Fasta" && <FastaTable sample={fastaInfo} />}
        {selectedTab === "Virulence" && <VirulenceTable data={virulenceInfo} />}
        {selectedTab === "AMR" && <AmrTable data={amrInfo} />}
      </Wrapper>
    </Container>
  );
};

export default Result;
